import math
def priority(task, state, m=2.0, map_factor=1.0, reduce_factor=1.0, join_factor=1.0,
             other_factor=1.0, k=2.0, slack_boost=0.5, overdue_boost=1.0,
             age=0.1, core_exp=0.3, p=1.0):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    wait = max(0.0, state.now - task.release)
    slack = task.due - est - state.now
    if slack >= 0.0:
        duef = 1.0 + slack_boost * math.exp(-slack / (k * mean))
    else:
        duef = 1.0 + slack_boost + overdue_boost * ((-slack) / mean)
    if task.task_type == 'map':
        typ = map_factor
    elif task.task_type == 'reduce':
        typ = reduce_factor
    elif task.task_type == 'join':
        typ = join_factor
    else:
        typ = other_factor
    tier = m if task.tenant == 'premium' else 1.0
    aging = 1.0 + age * wait / est
    cores = max(task.resource_need, 1e-6)
    return tier * typ * task.weight * aging * duef / ((est ** p) * (cores ** core_exp))

