def priority(task, state, m=5.0, c=1.0, a=0.5, b=0.2, rho=0.2, G=1e6):
    p = max(task.estimated_runtime, 1e-6)
    r = max(task.resource_need, 1e-6)
    mean = max(state.mean_est, 1e-6)
    wait = max(0.0, state.now - task.release)
    tier = m if task.tenant == 'premium' else 1.0
    base = tier * task.weight / (p * r ** rho)
    if task.tenant == 'premium':
        urgent = G if wait > c * (p + mean) else 0.0
        return base * (1.0 + a * wait / (p + mean)) + urgent
    else:
        return base * (1.0 + b * wait / (p + mean))

def priority(task, state, m=5.0, alpha=1.0, rho=0.0, age=0.25, pres=1.0, cap=3.0):
    p = max(task.estimated_runtime, 1e-6)
    r = max(task.resource_need, 1e-6)
    mean = max(state.mean_est, 1e-6)
    wait = max(0.0, state.now - task.release)
    pressure = state.queue_work / max(state.capacity * mean, 1e-6)
    if task.tenant == 'premium':
        tier = m * (1.0 + pres * min(pressure, cap))
    else:
        tier = 1.0
    age_factor = 1.0 + age * wait / (p + mean)
    return tier * task.weight * age_factor / (p ** alpha * r ** rho)

def priority(task, state, m=1.0, alpha=1.0, rho=0.1, age=0.4, pres=1.0, cap=3.0):
    p = max(task.estimated_runtime, 1e-6)
    r = max(task.resource_need, 1e-6)
    mean = max(state.mean_est, 1e-6)
    wait = max(0.0, state.now - task.release)
    pressure = state.queue_work / max(state.capacity * mean, 1e-6)
    base = task.weight * (1.0 + age * wait / (p + mean)) / (p ** alpha * r ** rho)
    if task.tenant == 'premium':
        return base + m * (1.0 + pres * min(pressure, cap))
    return base

def priority(task, state, m=5.0, alpha=1.0, rho=0.1, age=0.3, beta=1.0,
             type_map=1.0, type_reduce=1.0, type_join=1.0, type_other=1.0):
    p = max(task.estimated_runtime, 1e-6)
    r = max(task.resource_need, 1e-6)
    mean = max(state.mean_est, 1e-6)
    wait = max(0.0, state.now - task.release)
    pressure = state.queue_work / max(state.capacity * mean, 1e-6)
    expo = alpha + beta * pressure / (1.0 + pressure)
    if task.task_type == 'map':
        typ = type_map
    elif task.task_type == 'reduce':
        typ = type_reduce
    elif task.task_type == 'join':
        typ = type_join
    else:
        typ = type_other
    tier = m if task.tenant == 'premium' else 1.0
    age_factor = 1.0 + age * wait / (p + mean)
    return tier * typ * task.weight * age_factor / (p ** expo * r ** rho)

