def priority(task, state, m=10.0, p=0.95, b=0.2, c=0.5,
             map_scale=1.0, reduce_scale=1.0, join_scale=1.0, other_scale=1.0):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    if task.task_type == 'map':
        scale = map_scale
    elif task.task_type == 'reduce':
        scale = reduce_scale
    elif task.task_type == 'join':
        scale = join_scale
    else:
        scale = other_scale
    eff = max(est * scale, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    weight = max(task.weight, 1e-6)
    wait = max(0.0, state.now - task.release)
    slack = task.due - state.now - est
    late = max(0.0, -slack) / mean
    age = 1.0 + b * wait / eff
    return tier * weight / (eff ** p) * (age + c * late)

