import math
def priority(task, state, m=10.0, p=1.0, alpha=0.0, b=0.0, w=0.0, map_mult=1.0, reduce_mult=1.0, join_mult=1.0, other_mult=1.0, u=1.0, k=1.0):
    est = max(task.estimated_runtime, 1e-6)
    cores = max(task.resource_need, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    wait = max(0.0, state.now - task.release)
    if task.task_type == 'map':
        tm = map_mult
    elif task.task_type == 'reduce':
        tm = reduce_mult
    elif task.task_type == 'join':
        tm = join_mult
    else:
        tm = other_mult
    tier = m if task.tenant == 'premium' else 1.0
    weight = max(task.weight, 1e-6) ** w
    slack = task.due - state.now - est
    scale = max(k * mean_est, est, 1e-6)
    urg = 1.0
    if task.tenant == 'premium':
        urg += u * math.exp(-max(slack, 0.0) / scale)
        if slack < 0.0:
            urg += u * (-slack) / scale
    age = 1.0 + b * wait / max(est, mean_est, 1e-6)
    return tier * tm * weight * urg * age / (max(est ** p, 1e-6) * max(cores ** alpha, 1e-6))

