def priority(task, state, m=10.0, p=1.0, w=0.0, alpha=0.0, b=0.0,
             map_premium=1.0, reduce_premium=1.0, join_premium=1.0, other_premium=1.0,
             map_standard=1.0, reduce_standard=1.0, join_standard=1.0, other_standard=1.0,
             load_boost=0.0, load_scale=1.0):
    est = max(task.estimated_runtime, 1e-6)
    cores = max(task.resource_need, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    cap = max(state.capacity, 1e-6)
    load = state.queue_work / max(cap * mean_est, 1e-6)
    premium = task.tenant == 'premium'
    if premium:
        tier = m + load_boost * math.tanh(load * load_scale)
        if task.task_type == 'map':
            tm = map_premium
        elif task.task_type == 'reduce':
            tm = reduce_premium
        elif task.task_type == 'join':
            tm = join_premium
        else:
            tm = other_premium
    else:
        tier = 1.0
        if task.task_type == 'map':
            tm = map_standard
        elif task.task_type == 'reduce':
            tm = reduce_standard
        elif task.task_type == 'join':
            tm = join_standard
        else:
            tm = other_standard
    wait = max(0.0, state.now - task.release)
    age = max(1.0 + b * wait / max(est, mean_est, 1e-6), 1e-6)
    weight = max(task.weight, 1e-6) ** w
    denom = max(est ** p, 1e-6) * max(cores ** alpha, 1e-6)
    return tier * tm * weight * age / denom

