import math
def priority(task, state, m=8.0, k=3.0, p=1.0, q=0.0, b=0.05, h=1.0, L=20.0, c=0.05):
    rt = max(task.estimated_runtime, 1e-6)
    cores = max(task.resource_need, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    wait = max(0.0, state.now - task.release)
    base = tier * max(task.weight, 1e-6) / max((rt ** p) * (cores ** q), 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    load = state.queue_work / max(state.capacity * mean_est, 1e-6)

    if load >= h or state.queue_len >= L:
        return base * (1.0 + b * wait / rt)

    slack = max(0.0, task.due - state.now - rt)
    return base * math.exp(-slack / (k * mean_est)) * (1.0 + c * wait / rt)

