import math
def priority(task, state, m=10.0, g=2.0, boost=5.0, scale=1.0, r=0.0):
    est = max(task.estimated_runtime, 1e-6)
    need = max(task.resource_need, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    mean = max(state.mean_est, est, 1e-6)
    slack = task.due - state.now - est
    x = (slack - g * mean) / max(scale * mean, 1e-6)
    if x > 60.0:
        sig = 0.0
    elif x < -60.0:
        sig = 1.0
    else:
        sig = 1.0 / (1.0 + math.exp(x))
    return tier / (est * (need ** r)) * (1.0 + boost * sig)

