import math
def priority(task, state, m=10.0, f_map=1.0, f_reduce=1.0, f_join=1.0, f_other=1.0, beta=1.0, shrink=0.0):
    if task.tenant == 'premium':
        tier = m
    else:
        tier = 1.0
    if task.task_type == 'map':
        typ = f_map
    elif task.task_type == 'reduce':
        typ = f_reduce
    elif task.task_type == 'join':
        typ = f_join
    else:
        typ = f_other
    est = max(task.estimated_runtime + shrink * max(state.mean_est, 1e-6), 1e-6)
    weight = max(task.weight, 1e-6) ** beta
    return tier * typ * weight / est

