    est0 = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    eff = max(est0 + shrink * mean_est, 1e-6)
    wait = max(0.0, state.now - task.release)
    age = 1.0 + b * wait / eff
    weight = max(task.weight, 1e-6) ** beta
    res = max(task.resource_need, 1e-6) ** alpha
    if task.task_type == 'map':
        tf = f_map
    elif task.task_type == 'reduce':
